#include <iostream>

using namespace std;

int main(int argc, char const *argv[]){
    /* code */
    int num = 10;
    int num2 = 5;
    int num1;

    num1 = num + num2;

    cout << "La suma es: " << num1 << endl;

    num1 = num - num2;

    cout << "La resta es: " << num1 << endl;

    num1 = num2 - num;

    cout << "La resta inversa es: " << num1 << endl;

    num1 = num * num2;

    cout << "La multiplicacion es: " << num1 << endl;

    num1 = num / num2;

    cout << "La division es: " << num1 << endl;

    num1 = num2 / num;

    cout << "La division inversa es: " << num1 << endl;

    return 0;
}